'use server'

import { revalidateTag } from 'next/cache'
import { addPost } from './db'

export async function createPost(formData: FormData) {
  const title = formData.get('title') as string

  if (!title) {
    return { error: 'Title is required' }
  }

  // Simulate database delay
  await new Promise((resolve) => setTimeout(resolve, 500))

  addPost(title)

  // Invalidate the cache for the 'posts' tag
  // This ensures that the next fetch for data with this tag
  // will skip the cache and get fresh data.
  revalidateTag('posts')
}

import { getPosts } from './db'
import { createPost } from './actions'

export default async function Home() {
  const posts = await getPosts()

  return (
    <main>
      <h1>Posts</h1>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>{post.title}</li>
        ))}
      </ul>

      <form action={createPost}>
        <input type="text" name="title" placeholder="New Post Title" required />
        <button type="submit">Create Post</button>
      </form>
    </main>
  );
}

